<?php
require __DIR__.'/../lib/auth_admin.php';$u=require_admin();$newCode='';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['act']??'';if($act==='create_teacher'){$name=trim((string)($_POST['name']??''));if($name!==''){$newCode=random_code('GURU');$s=db()->prepare('INSERT INTO teachers(name,code_lookup,code_hash,active,created_at) VALUES(?,?,?,?,?)');$s->execute([$name,lookup_token($newCode),password_hash(strtoupper($newCode),PASSWORD_DEFAULT),1,now_sql()]);$msg='Kode guru dibuat. Salin sekarang karena kode tidak dapat ditampilkan ulang.';}}elseif($act==='toggle_teacher'){$id=(int)($_POST['id']??0);db()->prepare('UPDATE teachers SET active=1-active WHERE id=?')->execute([$id]);}}
$teachers=db()->query('SELECT t.*, (SELECT COUNT(*) FROM games g WHERE g.teacher_id=t.id) game_count FROM teachers t ORDER BY t.created_at DESC')->fetchAll();
$countGames=(int)db()->query('SELECT COUNT(*) FROM games')->fetchColumn();$countPub=(int)db()->query('SELECT COUNT(*) FROM games WHERE status="published"')->fetchColumn();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/style.css"><title>Admin Dashboard</title></head><body><div class="wrap"><div class="topbar"><div><div class="brand">ADMIN // CONTROL</div><h2><?=e($u['name'])?></h2></div><div class="nav"><a href="/">Portal</a><a href="logout.php">Keluar</a><button class="btn" data-theme-btn onclick="aghTheme()">Terang</button></div></div><div class="kpi"><div><span class="muted small">Guru</span><br><strong><?=count($teachers)?></strong></div><div><span class="muted small">Semua game</span><br><strong><?=$countGames?></strong></div><div><span class="muted small">Published</span><br><strong><?=$countPub?></strong></div></div><?php if($msg):?><div class="flash ok"><?=e($msg)?></div><?php endif?><?php if($newCode):?><div class="code-once"><?=e($newCode)?></div><?php endif?><div class="card" style="padding:18px;margin:16px 0"><h3>Buat akses guru</h3><form method="post" class="row"><input type="hidden" name="csrf" value="<?=e(ensure_csrf())?>"><input type="hidden" name="act" value="create_teacher"><input name="name" required placeholder="Nama guru" style="flex:1;min-width:220px;padding:12px;border-radius:12px;border:1px solid var(--border);background:#07101c;color:white"><button class="btn primary">Generate Kode</button></form></div><div class="card" style="padding:18px"><table class="table"><thead><tr><th>Guru</th><th>Game</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($teachers as $t):?><tr><td><strong><?=e($t['name'])?></strong><div class="small muted"><?=e($t['created_at'])?></div></td><td><?=$t['game_count']?></td><td><?= $t['active']?'<span class="badge">aktif</span>':'<span class="badge" style="color:var(--red)">nonaktif</span>'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(ensure_csrf())?>"><input type="hidden" name="act" value="toggle_teacher"><input type="hidden" name="id" value="<?=$t['id']?>"><button class="btn <?= $t['active']?'danger':'mag'?>"><?= $t['active']?'Nonaktifkan':'Aktifkan'?></button></form></td></tr><?php endforeach?></tbody></table></div></div><script src="../assets/theme.js"></script></body></html>
